'use strict';
/* Scene navigation layers on the existing resource workspace. */
const SceneTools=window.XDPScenes;
const TeaScripts=window.XDPTeaScripts;
const SCENE={tea:{topic:'birthday',messages:[],draft:'',link:'',summary:null,revision:0,saved:null},look:{photo:null,title:'把喜欢，留在这里',subtitle:'赵露思 · 生日共创',layout:'frame',x:50,y:50,zoom:100,goal:'帮我看看构图，建议一个优先修改方向',revision:0,saved:null,reply:null},join:{photo:null,text:'愿每一份喜欢，都有回应',sticker:'star',revision:0,saved:null,count:0},decision:{id:null,svg:'',layers:[],kind:'title',view:'after',revision:0,bingo:false,saved:null,changed:false,history:[],note:''},engine:'online',textConsent:false,imageConsent:false,busy:false,voiceListening:false,voiceMessage:'',error:'',notice:'',serial:0};

// Channels are isolated within this local demo. This is not server-side account privacy.
function sceneTeaState(){const group=SCENE.tea;if(group.channel!=='private')return group;group.privateBy=group.privateBy||{};return group.privateBy[ME]||(group.privateBy[ME]={topic:'birthday',messages:[TeaScripts.opening('birthday')],draft:'',link:'',summary:null,revision:0,saved:null});}
function sceneGuide(t=sceneTeaState()){t.guides=t.guides||{};return t.guides[ME]||(t.guides[ME]=SceneTools.newGuidance());}
function sceneChannel(){return SCENE.tea.channel==='private'?'private':'group';}
function sceneGuideHTML(){const g=sceneGuide();if(!g.audience)return `<section class="scene-guide" aria-label="选择引导方式"><h3>先从你现在的状态开始</h3><p>没有标准答案，之后可以随时切换。</p><div class="scene-audiences">${SceneTools.audiences.map(a=>`<button data-act="scene-audience" data-audience="${a.id}"><b>${esc(a.label)}</b><span>${esc(a.hint)}</span></button>`).join('')}</div></section>`;
 const stageNames={intent:'说说起点',feeling:'找找感觉',details:'保留与避开',confirm:'确认想法',collected:'收集灵感'};
 return `<section class="scene-guide" aria-label="当前引导步骤"><div class="scene-guide-title"><span>${esc(SceneTools.audiences.find(a=>a.id===g.audience)?.label)} · ${stageNames[g.stage]}</span><button data-act="scene-guide-restart" class="btn btn-ghost btn-sm" ${SCENE.busy?'disabled':''}>调整起点</button></div><p>${esc(SceneTools.guidePrompt(g))}</p>${g.stage==='intent'&&g.audience==='explore'?'<div class="scene-chips">'+['纪念一个瞬间','送一句祝福','做一张聚会海报'].map(text=>`<button data-act="scene-guide-seed" data-text="${text}">${text}</button>`).join('')+'</div>':''}${g.stage==='details'&&g.audience==='ready'?sceneButton('scene-guide-feeling','我还想看看感觉，再往下聊'):''}${g.stage==='feeling'?sceneMoodHTML():''}${['confirm','collected'].includes(g.stage)?`${sceneBriefHTML(g)}${g.stage==='confirm'?`<label class="scene-rights-label" for="scene-guide-rights">用图先确认<select id="scene-guide-rights" class="input"><option value="pending" ${g.rights==='pending'?'selected':''}>尚未确认</option><option value="granted" ${g.rights==='granted'?'selected':''}>自有图片 / 已获授权</option><option value="explore" ${g.rights==='explore'?'selected':''}>仅探索，先不使用未授权图片</option></select></label>${sceneButton('scene-guide-confirm','就是这个方向，先记住','',true)}<p class="scene-caption">确认只保留当前想法，不会发到灵感池，也不会自动搜索。</p>`:`<div class="scene-actions">${sceneButton('scene-guide-save',g.saved?'已分享到灵感池':sceneChannel()==='private'?'确认分享到公共灵感池':'收进灵感池',g.saved?'disabled':'',true)}${sceneButton('scene-guide-references',SCENE.engine==='local'?'在线模式可找图片参考':'按这个方向找图片参考',SCENE.busy||SCENE.engine==='local'?'disabled':'')}${sceneButton('scene-pool','去灵感池选图')}${sceneButton('scene-guide-edit','再改一下方向')}</div>${g.audience==='guided'?'<details class="scene-guide-howto"><summary>不会操作？跟着做第一张</summary><ol><li>先上传 1–2 张你有权使用的图片到灵感池。</li><li>勾选图片，再点「用所选图片拼贴」。</li><li>一次选一张图层，先移动，再试取景和大小。</li><li>留下一版后，只选一个细项写下想改的地方。</li></ol></details>':''}<p class="scene-caption">找参考才会联网；图片来源与授权需逐张核对，方向可以继续改。</p>`}`:''}</section>`;
}
function sceneBriefHTML(g){if(g.stage==='confirm')return `<div class="scene-brief-edit">${[['intent','想做什么',600],['feeling','想要的感觉（可改）',300],['details','必留的元素 / 不想出现的内容',1000]].map(([key,label,max])=>`<label for="scene-guide-edit-${key}">${label}<textarea class="input" id="scene-guide-edit-${key}" data-guide-edit="${key}" maxlength="${max}" rows="2">${esc(g[key])}</textarea></label>`).join('')}</div>`;return `<dl class="scene-brief"><dt>想做什么</dt><dd>${esc(g.intent)}</dd><dt>想要的感觉</dt><dd>${esc(g.feeling||'已有明确方向，未另外指定')}</dd><dt>保留 / 避开</dt><dd>${esc(g.details)}</dd><dt>用图状态</dt><dd>${g.rights==='granted'?'自有 / 已获授权':g.rights==='explore'?'仅探索，暂不使用未授权图片':'尚未确认；不会视为已获授权'}</dd></dl>`;}
function sceneMoodHTML(){return `<div class="scene-mood-grid" aria-label="情绪板选择">${SceneTools.moods.map(m=>`<button class="scene-mood" data-act="scene-mood" data-mood="${m.id}" aria-label="选择${m.label}"><svg viewBox="0 0 240 128" role="img" aria-label="${m.label}颜色与留白示意"><rect width="240" height="128" fill="${m.colors[0]}"/><rect x="16" y="14" width="94" height="100" rx="2" fill="${m.colors[1]}"/><circle cx="63" cy="50" r="18" fill="${m.colors[2]}" opacity=".6"/><path d="M31 97Q60 58 95 97" fill="${m.colors[2]}" opacity=".4"/><rect x="127" y="38" width="83" height="8" fill="${m.colors[2]}"/><rect x="127" y="56" width="55" height="3" fill="${m.colors[2]}"/><circle cx="204" cy="99" r="9" fill="${m.colors[1]}"/></svg><b>${esc(m.label)}</b><span>${esc(m.words)}</span><small>${esc(m.tip)}</small></button>`).join('')}</div><p class="scene-caption">原创色彩与留白示意，不是照片参考或定稿。不喜欢任何一张，也可以在下面描述自己的感觉。</p>`;}
function sceneChangeChannel(channel){if(SCENE.busy||!['group','private'].includes(channel))return;window.XDPVoice?.cancel();SCENE.tea.channel=channel;SCENE.error='';SCENE.notice='';paintScene();}
function sceneChooseAudience(id){if(SCENE.busy||!SceneTools.audiences.some(a=>a.id===id))return;const g=sceneGuide();Object.assign(g,SceneTools.newGuidance(),{audience:id});SCENE.notice='';paintScene();}
function sceneSaveGuidance(){const t=sceneTeaState(),g=sceneGuide(t);if(!g.confirmed||g.saved)return;const source=t.messages.filter(m=>m.role==='user'&&m.by===ME&&(g.sourceIds||[]).includes(m.id));const id=sceneId('P');S.pool.unshift({id,name:'已确认方向 · '+g.intent.slice(0,22),note:SceneTools.guideBrief(g),by:ME,cat:'direction',kind:'insp',likes:[],cmts:[],taken:false,sourceIds:source.map(m=>m.id),sourceChannel:sceneChannel(),guidance:JSON.parse(JSON.stringify(g)),rights:g.rights});g.saved=id;SCENE.notice='已按你的操作分享到公共灵感池；尚未视为成品或全体共识。';paintStudioShell();paintScene();}
async function sceneFindGuidanceReferences(){if(SCENE.engine!=='online'){SCENE.error='本地模式不联网。可在话题与设置中切换在线模式，再主动找参考。';sceneSync();return;}const t=sceneTeaState(),g=sceneGuide(t);if(!g.confirmed||g.stage!=='collected'){SCENE.error='先确认这次的方向，再找图片参考。';sceneSync();return;}await sceneTask(async()=>{const rev=t.revision;const r=await fetch('/api/references/search',{method:'POST',headers:{'Content-Type':'application/json'},signal:AbortSignal.timeout(165000),body:JSON.stringify({goal:SceneTools.guideBrief(g),topic:t.topic,consent:true,guidance:{...g,referenceRequested:true}})});const data=await r.json();if(!r.ok)throw Error(data.error||'参考暂未找到，方向仍保留。');if(t.revision!==rev)return;t.messages.push({id:sceneId('AI'),role:'assistant',engine:'online',text:'这些是按已确认方向找到的候选参考，先看是不是你想要的感觉；不是成品，也还没有加入灵感池。',references:data.references||[],search:data.search});});}
function sceneSaveReference(messageId,referenceId){const t=sceneTeaState(),m=t.messages.find(m=>m.id===messageId),r=m?.references?.find(r=>r.id===referenceId);if(!r||!SceneTools.safeLink(r.url)||(m.savedReferences||[]).includes(referenceId))return;const id=sceneId('P');S.pool.unshift({id,name:'链接参考 · '+r.title,note:'作者：'+(r.creator||'请到原页核对')+'；许可：'+(r.license||'请到原页核对')+'。此处仅收集来源链接，获得使用权后上传原图才能拼贴。',by:ME,cat:'visual',kind:'insp',likes:[],cmts:[],taken:false,referenceURL:r.url,referenceCreator:r.creator,referenceLicense:r.license,referenceLicenseURL:r.licenseURL,sourceChannel:sceneChannel(),sourceIds:[messageId]});m.savedReferences=m.savedReferences||[];m.savedReferences.push(referenceId);SCENE.notice='已收集来源链接与署名；没有下载图片，也没有假定你已取得使用权。';paintScene();}
async function sceneGroupSpark(){if(sceneChannel()!=='group')return;const t=sceneTeaState(),messages=t.messages.filter(m=>m.role==='user');if(!messages.length)return;await sceneTask(async()=>{const context=t.messages.slice(-8);if(!context.some(m=>m.role==='user'))throw Error('最近对话没有可引用的成员发言，先听一条新想法再启发。');const proposed=SceneTools.spark(context),rev=t.revision;const result=SCENE.engine==='local'?{reply:proposed.text}:await sceneRequest('tea','从大家已说的内容提出一个新的可选灵感，不代替任何人确认。',null,{action:'spark'});if(t.revision===rev)t.messages.push({id:sceneId('AI'),role:'assistant',engine:SCENE.engine,text:result.reply,proposal:true,sourceIds:proposed.sourceIds});});}
function sceneSaveProposal(id){const t=sceneTeaState(),m=t.messages.find(m=>m.id===id&&m.proposal);if(!m||m.saved)return;const idPool=sceneId('P');S.pool.unshift({id:idPool,name:'AI 提议 · 待大家讨论',note:m.text,by:ME,kind:'insp',cat:'direction',likes:[],cmts:[],taken:false,sourceIds:m.sourceIds.slice(),aiGenerated:true,sourceChannel:'group',confirmedBy:ME});m.saved=idPool;SCENE.notice='已收为待讨论灵感，保留真实发言来源；不表示大家同意。';paintScene();}


// Use the existing pool, not a second collection of disconnected sample images.
const sceneOriginalPoolPanel=poolPanelHTML,sceneOriginalPoolCard=poolCardHTML;
SCENE.poolSelected=new Set();
for(const category of [{k:'direction',e:'',t:'方向与提议'},{k:'mood',e:'',t:'感觉与情绪'},{k:'palette',e:'',t:'色彩'},{k:'layout',e:'',t:'构图与版式'}])if(!POOL_CATS.some(c=>c.k===category.k))POOL_CATS.push(category);
poolPanelHTML=function(){return `<section class="scene-pool-tools" aria-label="从灵感池开始拼贴"><div><h3>从不同灵感里，各取一点喜欢</h3><p>勾选多张已上传的图片，带进同一张画面；每张都能独立取景、移动、缩放和旋转。</p></div><div class="scene-actions"><span id="scene-pool-selection-count">已选 ${SCENE.poolSelected.size} 张</span>${sceneButton('scene-pool-collage','用所选图片拼贴',SCENE.poolSelected.size?'':'disabled',true)}${sceneButton('scene-pool-upload','上传我的素材到灵感池')}${sceneButton('scene-go','回茶话室找方向','data-page="tea"')}</div><p class="scene-caption">链接参考与示例占位卡不是可用图片；请先上传你有权使用的原图。选中不等于已采用，保存稿件才记录来源。</p></section>`+sceneOriginalPoolPanel();};
poolCardHTML=function(p,i){let base=sceneOriginalPoolCard(p,i);if(p.referenceURL)base=base.replace(/<div class="material-visual">[\s\S]*?<\/svg><\/div>/,'<div class="scene-link-placeholder">来源链接 · 未导入图片</div>');if(p.guidance)base=base.replace(/<div class="material-visual">[\s\S]*?<\/svg><\/div>/,()=>'<div class="scene-link-placeholder">已确认的想法 · '+esc(p.guidance.feeling||'按已描述方向')+'<small>方向卡，不是成品稿</small></div>');if(p.referenceURL&&SceneTools.safeLink(p.referenceURL))return base.replace(/^(\s*<(?:div|article)[^>]*>)/,(_,open)=>open+'<p class="scene-reference-origin"><a href="'+esc(p.referenceURL)+'" target="_blank" rel="noopener noreferrer">打开参考原页 ↗</a><small>链接参考 · 未导入图片 · 使用前核对授权</small></p>');if(!SceneTools.imageSafe(p.dataUrl))return base;const pick=`<label class="scene-pool-pick"><input type="checkbox" data-pool-collage="${esc(p.id)}" ${SCENE.poolSelected.has(p.id)?'checked':''}>选进拼贴 · 保留 ${esc(P(p.by).name)} 的来源</label>`;return base.replace(/^(\s*<(?:div|article)[^>]*>)/,(_,open)=>open+pick);};
function scenePoolSelectionSync(){const count=$('#scene-pool-selection-count');if(count)count.textContent='已选 '+SCENE.poolSelected.size+' 张';const b=$('[data-act="scene-pool-collage"]');if(b)b.disabled=!SCENE.poolSelected.size||!!SCENE.look.poolImporting;}
async function sceneImportPoolImages(){if(SCENE.look.poolImporting)return;const selected=[...new Map(S.pool.filter(p=>SCENE.poolSelected.has(p.id)&&SceneTools.imageSafe(p.dataUrl)).map(p=>[p.id,p])).values()];if(!selected.length)return;const c=lookCollage();if(selected.length!==SCENE.poolSelected.size){SCENE.error='所选项目中包含链接或非图片，请只选已上传的图片。';toast(SCENE.error);return;}if(c.materials.length+selected.length>16){toast('每张画面最多 16 份素材，请减少选择。');return;}SCENE.look.poolImporting=true;scenePoolSelectionSync();try{const additions=[],columns=selected.length===1?1:selected.length<=4?2:4,rows=Math.ceil(selected.length/columns),cellW=480/columns,cellH=500/rows;for(const p of selected){const img=await sceneDecode(p.dataUrl);if(img.width*img.height>60000000)throw Error('图片像素过大，请先缩小后上传。');additions.push({id:sceneId('material'),name:p.name,url:p.dataUrl,width:img.width,height:img.height,x:60+cellW*(additions.length%columns+.5),y:100+cellH*(Math.floor(additions.length/columns)+.5),scale:Math.max(20,Math.round(Math.min(1,cellW*.84/280,cellH*.84/(280*img.height/img.width))*100)),angle:0,sourcePoolId:p.id,sourceBy:p.by,cropX:50,cropY:50,cropW:100,cropH:100});}c.materials.push(...additions);c.selected=additions.at(-1).id;SCENE.look.layout='free';SCENE.poolSelected.clear();sceneDirty('look');sceneGo('look');SCENE.notice='已带入 '+additions.length+' 张来源图片。选中每一层，可只取图中的一部分；原图不变。';sceneSync();}catch(e){toast('未导入：'+e.message);}finally{SCENE.look.poolImporting=false;scenePoolSelectionSync();}}
function sceneReviewHTML(){const a=sceneDecisionBase(),d=SCENE.decision,aspect=d.reviewAspect||'feeling',labels={feeling:'整体感觉',palette:'配色',layout:'构图与留白',type:'字体与文案',element:'图片与装饰元素'};return `<section class="scene-review-details" aria-label="稿件细项反馈"><h3>把比较拆细，留下下一条灵感</h3><p>先选一个细项，再写具体喜欢或想改的部分。这里收集意见，不会自动改图或替大家定稿。</p><div class="scene-chips">${Object.entries(labels).map(([key,label])=>`<button data-act="scene-review-aspect" data-aspect="${key}" aria-pressed="${aspect===key}">${label}</button>`).join('')}</div><label for="scene-review-note">${labels[aspect]} · 你的观察<textarea class="input" id="scene-review-note" maxlength="600" placeholder="例如：喜欢 A 的留白，想保留 B 的小花，但标题可以再清楚一点。">${esc(d.reviewDraft||'')}</textarea></label>${sceneButton('scene-review-save','收为一条细项灵感',!a?'disabled':'',true)}<ul>${(a?.reviewNotes||[]).map(n=>`<li><b>${esc(labels[n.aspect]||n.aspect)} · ${esc(P(n.by).name)}</b><p>${esc(n.text)}</p></li>`).join('')||'<li>还没有细项反馈，可以先留一句观察。</li>'}</ul></section>`;}
function sceneSaveReview(){const d=SCENE.decision,a=sceneDecisionBase(),text=SceneTools.clean(d.reviewDraft,600),aspect=d.reviewAspect||'feeling';if(!a||!text){SCENE.error='先写下一条具体观察，再收集。';sceneSync();return;}a.reviewNotes=a.reviewNotes||[];if(a.reviewNotes.some(n=>n.by===ME&&n.aspect===aspect&&n.text===text)){SCENE.notice='这条观察已经收集过了。';sceneSync();return;}const id=sceneId('P');a.reviewNotes.push({id,by:ME,aspect,text});S.pool.unshift({id,name:'稿件细项 · '+a.id,note:text,by:ME,cat:({feeling:'mood',palette:'palette',layout:'layout',type:'copy',element:'element'})[aspect],kind:'insp',likes:[],cmts:[],taken:false,sourceArtId:a.id,reviewAspect:aspect});d.reviewDraft='';sceneAwardQuest('feedback',id);SCENE.notice='已保留稿件来源与反馈细项，收进灵感池。';paintScene();}


// Quest rewards use the existing heart ledger; there is no parallel currency or message-streak payout.
function sceneGamePlayer(){SCENE.game=SCENE.game||{players:{},effects:true};return SCENE.game.players[ME]||(SCENE.game.players[ME]={claimed:{},eggOpened:false,eggPrompt:null,burstPending:false});}
function sceneBuddySVG(){return '<svg class="scene-buddy" viewBox="0 0 48 48" aria-hidden="true"><circle cx="13" cy="11" r="8" fill="#9A7DB0"/><circle cx="35" cy="11" r="8" fill="#9A7DB0"/><circle cx="13" cy="11" r="4" fill="#E8D9EF"/><circle cx="35" cy="11" r="4" fill="#E8D9EF"/><ellipse cx="24" cy="27" rx="21" ry="18" fill="#D8C3E6"/><path d="M6 23Q15 14 24 24Q33 14 42 23L37 33Q28 35 24 28Q20 35 11 33Z" fill="#806191"/><ellipse class="buddy-eye" cx="15" cy="25" rx="2" ry="3" fill="#FFF9EE"/><ellipse class="buddy-eye" cx="33" cy="25" rx="2" ry="3" fill="#FFF9EE"/><path d="M20 33Q24 37 28 33" fill="none" stroke="#63476D" stroke-width="2" stroke-linecap="round"/><path d="m21 29 3 3 3-3" fill="#63476D"/><circle cx="10" cy="33" r="3" fill="#E5ACCA"/><circle cx="38" cy="33" r="3" fill="#E5ACCA"/></svg>';}
function sceneGameHTML(){const player=sceneGamePlayer(),completed=Object.keys(player.claimed).length,earned=Object.values(player.claimed).reduce((n,q)=>n+q.points,0),burst=player.burstPending;player.burstPending=false;return `<aside class="scene-game ${SCENE.game.effects?'':'game-effects-off'} ${burst?'is-new':''}" aria-label="灵感小冒险"><div class="scene-game-face">${sceneBuddySVG()}</div><div class="scene-game-name"><b>灵感小冒险</b><span>${SceneTools.gameRank(completed)}</span></div><div class="scene-game-progress"><progress value="${completed}" max="3" aria-label="已点亮的灵感任务"></progress><span>${completed}/3</span></div><span class="scene-game-score" role="status" aria-live="polite">闯关 +${earned} 颗心</span><details class="scene-game-book"><summary>${completed>=2&&!player.eggOpened?'手册 · 有彩蛋':'闯关手册'}</summary><div class="scene-game-book-body"><h3>随你顺序，不用赶进度</h3><p>不靠发消息刷分。每位演示成员每关只领奖一次，奖励沿用本页的颗心。</p><ol>${SceneTools.gameQuests.map(q=>`<li class="${player.claimed[q.id]?'is-done':''}"><b>${player.claimed[q.id]?'✓ ':''}${esc(q.title)} <span>+${q.points}</span></b><p>${esc(q.tip)}</p></li>`).join('')}</ol><p class="scene-caption">私聊确认也能获得方向奖励。积分仅作本页体验，刷新重置，不兑换现金或奖品。</p>${completed>=2?`<section class="scene-game-egg"><b>阿浣藏了一张灵感小纸条</b>${player.eggOpened?`<p>${esc(player.eggPrompt)}</p>${sceneButton('scene-game-egg-draft','放进私聊草稿，不发送')}`:`<p>两关点亮啦。拆开看看，是一个不额外花分的小挑战。</p>${sceneButton('scene-game-egg','拆开灵感彩蛋','',true)}`}<small>本地预设灵感挑战，不是实时 AI 生成或付费抽奖。</small></section>`:''}</div></details><button class="scene-game-effects" data-act="scene-game-effects" aria-pressed="${SCENE.game.effects}" title="只控制惊喜动效，不影响奖励">惊喜${SCENE.game.effects?'开':'关'}</button></aside>`;}
function sceneAwardQuest(key,sourceId){const rule=SceneTools.gameQuests.find(q=>q.id===key),player=sceneGamePlayer();if(!rule||player.claimed[key])return false;let valid=false;if(key==='direction'){const g=sceneGuide();valid=g.confirmed===true&&g.stage==='collected'&&!!g.intent.trim()&&!!g.details.trim()&&['granted','explore'].includes(g.rights);}else if(key==='collage'){valid=S.arts.some(a=>a.id===sourceId&&a.author===ME&&a.sceneComposed);}else if(key==='feedback'){valid=S.pool.some(p=>p.id===sourceId&&p.by===ME&&p.reviewAspect&&SceneTools.gameFeedbackEligible(p.note));}if(!valid)return false;player.claimed[key]={points:rule.points,sourceId:sourceId||'direction-'+sceneChannel(),by:ME};addHeart(rule.points,rule.title+' · 灵感闯关',{silent:true});const event=S.heart.events[0];if(event)Object.assign(event,{by:ME,quest:key,sourceId:player.claimed[key].sourceId});player.burstPending=SCENE.game.effects&&!reduceMotion();toast(rule.cheer+' +'+rule.points+' 颗心');return true;}
function sceneOpenGameEgg(){const player=sceneGamePlayer();if(Object.keys(player.claimed).length<2)return false;if(!player.eggOpened){player.eggOpened=true;const index=Array.from(ME).reduce((n,c)=>n+c.codePointAt(0),0)%SceneTools.gamePrompts.length;player.eggPrompt=SceneTools.gamePrompts[index];}paintScene();return true;}
function sceneGameEggDraft(){const player=sceneGamePlayer();if(!player.eggOpened||!player.eggPrompt||SCENE.busy)return;const previousChannel=SCENE.tea.channel;SCENE.tea.channel='private';const t=sceneTeaState(),text=player.eggPrompt;if(t.draft.includes(text)){SCENE.notice='这张小纸条已经在你的私聊草稿里，没有发送。';}else if((t.draft+(t.draft?'\n':'')+text).length>600){SCENE.tea.channel=previousChannel;SCENE.error='私聊草稿放不下这张小纸条，先处理原草稿；没有覆盖或发送文字。';sceneSync();return;}else{t.draft+=(t.draft?'\n':'')+text;SCENE.notice='小纸条放进私聊草稿了。想好了再发，不着急。';}window.XDPVoice?.cancel();WORK.page='tea';paintStudioShell();paintScene();}

const sceneLegacy={paintWorkspace,paintStudioShell,workNavMarkup,workCurrentNav};
const sceneId=prefix=>prefix+'-'+Date.now()+'-'+(++SCENE.serial);
const sceneName=()=>SceneTools.scenes.find(s=>s.id===WORK.page)?.name;
function sceneGo(page){SCENE.error='';SCENE.notice='';SCENE.textConsent=false;SCENE.imageConsent=false;workEnter(page);}
workCurrentNav=function(){return sceneName()?WORK.page:'resources';};
workNavMarkup=function(){const active=workCurrentNav();return [...SceneTools.scenes.map(s=>({key:s.id,label:s.name,icon:s.icon})),{key:'resources',label:'素材与作品',icon:'layers'}].map(s=>
`<button class="studio-nav ${active===s.key?'active':''}" data-act="scene-go" data-page="${s.key}" ${active===s.key?'aria-current="page"':''}>${uiIcon(s.icon)}<span>${s.label}</span></button>`).join('');};
paintStudioShell=function(){sceneLegacy.paintStudioShell();const loc=$('#studio-location');if(loc)loc.textContent=sceneName()||(WORK.page==='resources'?'素材与作品':['assistant','compose','discussion','remix','detail'].includes(WORK.page)?({assistant:'设计助手',compose:'模板与素材',discussion:'历史讨论',remix:'海报二创',detail:'作品详情'}[WORK.page]):!WORK.page?(S.stage===1?'项目概览':S.boardView==='pool'?'灵感池':S.boardView==='done'?'稿件评审':'项目资料'):loc.textContent);};
paintWorkspace=function(){if(sceneName()||WORK.page==='resources'){paintScene();return;}sceneLegacy.paintWorkspace();};
function sceneButton(act,text,extra='',primary=false){return `<button class="btn ${primary?'btn-primary':''}" data-act="${act}" ${extra}>${text}</button>`;}
function sceneMessage(text){return `<p class="scene-caption">${esc(text)}</p>`;}
function sceneToolsHTML(images=false){const local=SCENE.engine==='local',offline=typeof location!=='undefined'&&location.protocol==='file:';return `<section class="scene-ai-tools" aria-label="助手设置"><label for="scene-engine">助手模式<select id="scene-engine" aria-label="助手模式" class="input" ${SCENE.busy?'disabled':''}><option value="online" ${!local?'selected':''} ${offline?'disabled':''}>在线 AI · 逐步引导</option><option value="local" ${local?'selected':''}>本地引导 · 不联网</option></select></label><span id="scene-engine-label" class="scene-live-label">${local?'本地规则引导 · 非 AI 分析':'银河智算 · 在线 AI'}</span><p id="scene-engine-note" class="scene-caption" data-images="${images?'1':'0'}">${local?'本地模式不会发送文字或图片，不联网检索；可继续排版、保存和下载。':(images?'点击 @AI 助手，即发送':'点击发送，即发送')+(images?'当前问题和预览图片':'当前问题与最近 8 条对话')+'给银河智算；先逐步确认想法；只有点击找参考才会检索。'}</p></section>`;}
function sceneReferencesHTML(message){if(!message.search)return '';const search=message.search;return `<section class="scene-reference-results"><p class="scene-caption">${esc(search.message||'')} ${search.provider?'· '+esc(search.provider):''}</p>${message.references?.length?`<div class="scene-reference-grid">${message.references.map(ref=>`<article class="scene-reference-card"><a href="${esc(ref.url)}" target="_blank" rel="noopener noreferrer">${ref.thumbnail?`<img src="${esc(ref.thumbnail)}" alt="${esc(ref.title)}" loading="lazy" referrerpolicy="no-referrer">`:`<span class="scene-reference-domain">${esc(ref.domain)}</span>`}<b>${esc(ref.title)}</b><span>${esc(ref.domain)} ↗</span></a><small>${esc(ref.creator)} · ${esc((ref.license||'使用条件见原页').toUpperCase())}${ref.licenseVersion?' '+esc(ref.licenseVersion):''}</small>${sceneButton('scene-reference-save',(message.savedReferences||[]).includes(ref.id)?'已收集链接':'收进灵感池（链接）','data-message="'+esc(message.id)+'" data-reference="'+esc(ref.id)+'" '+((message.savedReferences||[]).includes(ref.id)?'disabled':''))}${ref.licenseURL?`<a class="scene-reference-license" href="${esc(ref.licenseURL)}" target="_blank" rel="noopener noreferrer">查看授权</a>`:''}</article>`).join('')}</div><p class="scene-caption">这些是联网找到的候选参考，不是新生成的设计稿；使用前请到原页核对作者和授权。</p>`:''}</section>`;}
function sceneScriptHTML(){const t=sceneTeaState(),script=TeaScripts.scenario(t.topic),count=t.exampleStep||0;return `<section class="scene-script-guide"><div class="scene-prompt-list">${script.prompts.map((text,i)=>`<button type="button" data-act="scene-script-prompt" data-i="${i}">${esc(text)}</button>`).join('')}</div><details class="scene-script-example"><summary>看一段示例对话 <small>据 PPT 第 ${script.sourceSlides.join('、')} 页改编</small></summary><p class="scene-caption">以下是脚本演示，用户 A/B/C 不是当前在线成员；未实际上传的图片不作分析。</p><div class="scene-script-feed">${script.turns.slice(0,count).map(turn=>`<article class="scene-bubble ${turn.role==='user'?'is-mine':''}"><b>${esc(turn.speaker)}${turn.adapted?' · 改编':''}</b><p>${esc(turn.text)}</p>${turn.action?sceneButton('scene-script-action',turn.action==='templates'?'打开现有模板':'用这个方向试一版',`data-page="${turn.action}" data-layout="${turn.layout||'frame'}"`):''}</article>`).join('')}</div><div class="scene-actions">${sceneButton('scene-script-next',count?'继续这段对话':'开始播放示例',count>=script.turns.length?'disabled':'')}${count?sceneButton('scene-script-reset','重新看'):''}</div></details></section>`;}
function sceneTipsHTML(){return `<details class="scene-tips"><summary>${uiIcon('note')} Tips 基地 · 不会做，也能开始</summary><div class="scene-tip-list">${SceneTools.tips.map(t=>`<details><summary>${esc(t.title)}<small>${esc(t.sub)}</small></summary><p>${esc(t.body)}</p><ol>${t.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${sceneButton('scene-tip-use','用这个方向试一版',`data-layout="${t.layout}"`)}</details>`).join('')}</div></details>`;}
function paintScene(){
 const s=SceneTools.scenes.find(s=>s.id===WORK.page),host=$('#stage-host');if(!host)return;const active=document.activeElement,focus=host.contains(active)&&active.id?{id:active.id,start:active.selectionStart,end:active.selectionEnd}:null;const previousPage=host.dataset.scenePage,scrollTop=host.querySelector('.stage')?.scrollTop||0;const openDetails=previousPage===WORK.page?[...host.querySelectorAll('details[open]')].map(d=>d.className):[];
 host.innerHTML=`<section class="stage"><div class="studio-content work-content scene-content"><header class="scene-heading"><div><span class="studio-eyebrow">OUR CO-CREATION ROOM</span><h1>${s?s.name:'素材与作品'}</h1><p>${s?s.tag:'想法、原图、模板和每一版作品，都能回到这里。'}</p></div><span class="scene-session">本页体验 · 未连接真实群聊</span></header>${s?`<div class="scene-path" aria-label="共创路径">${SceneTools.scenes.map((x,i)=>`<button data-act="scene-go" data-page="${x.id}" ${s.id===x.id?'aria-current="page"':''}><span>0${i+1}</span>${x.name}</button>`).join('')}</div>`:''}${s?sceneGameHTML():''}<p id="scene-error" class="work-error" role="alert">${esc(SCENE.error)}</p><p id="scene-notice" class="scene-notice" role="status">${esc(SCENE.notice)}</p>${WORK.page==='tea'?sceneTeaHTML():WORK.page==='look'?sceneLookHTML():WORK.page==='join'?sceneJoinHTML():WORK.page==='decision'?sceneDecisionHTML():sceneResourcesHTML()}${s?sceneTipsHTML():''}<p class="scene-memory">本页草稿与版本刷新后会清空；点击 @AI 时会发送按钮旁说明的内容。下载可保留当前预览。</p></div></section>`;
 host.dataset.scenePage=WORK.page;const feed=host.querySelector('.scene-feed');if(feed){const guide=feed.querySelector('.scene-guide');feed.scrollTop=guide?Math.max(0,feed.scrollTop+guide.getBoundingClientRect().top-feed.getBoundingClientRect().top-12):feed.scrollHeight;}if(previousPage===WORK.page){const stage=host.querySelector('.stage');if(stage)stage.scrollTop=scrollTop;if(focus){const field=document.getElementById(focus.id);if(field){field.focus({preventScroll:true});if(typeof focus.start==='number'&&field.setSelectionRange)field.setSelectionRange(focus.start,focus.end);}}for(const name of openDetails){const detail=[...host.querySelectorAll('details')].find(d=>d.className===name);if(detail)detail.open=true;}}sceneSync();
}
function sceneTeaHTML(){const t=sceneTeaState(),local=SCENE.engine==='local',voice=window.XDPVoice?.available()===true;return `<div class="scene-tea-layout scene-chat-room"><section class="scene-paper scene-chat-panel" aria-label="共创聊天室"><header class="scene-chat-header"><div><h2>${sceneChannel()==='private'?'先和 AI 理清自己的想法':'大家一起聊，让灵感接着长'}</h2><p><span id="scene-tea-engine-label">${local?'阿浣 · 本地引导':'阿浣 · AI 灵感搭子'}</span> · 本页活动演示</p></div><div class="scene-chat-header-actions">${sceneButton('scene-summary','整理讨论',!t.messages.some(m=>m.role==='user')||SCENE.busy?'disabled':'')}${sceneChannel()==='group'?sceneButton('scene-group-spark','从聊天里找新灵感',!t.messages.some(m=>m.role==='user')||SCENE.busy?'disabled':''):''}${sceneButton('scene-go','去试图','data-page="look"')}<details class="scene-chat-options"><summary>话题与设置</summary><div class="scene-chat-options-body"><div class="scene-chips">${TeaScripts.scenarios.map(x=>`<button data-act="scene-topic" data-topic="${x.id}" aria-pressed="${t.topic===x.id}">${esc(x.label)}</button>`).join('')}</div>${sceneScriptHTML()}<details class="scene-manual-source"><summary>补充自己的参考链接（选填）</summary><label for="scene-tea-link">参考网址</label><input class="input" id="scene-tea-link" type="url" placeholder="https://" value="${esc(t.link)}"></details>${sceneToolsHTML()}${sceneTipsHTML()}</div></details></div></header><div class="scene-channel-tabs" role="group" aria-label="选择聊天范围"><button data-act="scene-channel" data-channel="group" aria-pressed="${sceneChannel()==='group'}" ${SCENE.busy?'disabled':''}>大群共创</button><button data-act="scene-channel" data-channel="private" aria-pressed="${sceneChannel()==='private'}" ${SCENE.busy?'disabled':''}>和 AI 私聊</button><span>${sceneChannel()==='private'?'当前成员的独立草稿；主动分享才进公共池':'大家的发言可以碰出新方向，不自动视为共识'}</span></div><div class="scene-feed" role="log" aria-label="当前话题消息" aria-live="polite" aria-relevant="additions text">${t.messages.map(m=>`<article class="scene-bubble ${m.role==='user'?'is-mine':''}"><b>${m.role==='user'?esc(P(m.by).name):m.scripted?'阿浣 · AI 开场脚本':m.engine==='online'?'阿浣 · AI 灵感搭子':'阿浣 · 本地引导 · 非 AI 分析'}</b><p>${esc(m.text)}</p>${sceneReferencesHTML(m)}${m.proposal?sceneButton('scene-proposal-save',m.saved?'已收集':'收为待讨论灵感','data-message="'+esc(m.id)+'" '+(m.saved?'disabled':'')):''}${m.recommendation?sceneButton('scene-ai-template','试试这个模板 →',`data-key="${esc(m.recommendation.key)}"`):''}${m.link?`<a href="${esc(m.link)}" target="_blank" rel="noopener noreferrer">打开成员分享的来源 ↗</a>`:''}</article>`).join('')}${SCENE.busy?`<article class="scene-bubble scene-chat-pending" role="status"><b>${local?'本地引导':'AI 设计助手'}</b><p>${local?'正在整理想法…':'阿浣正在接住这个想法…'}</p></article>`:''}${t.summary?sceneTeaSummaryHTML():''}${sceneGuideHTML()}</div><form id="scene-tea-form" class="scene-form scene-composer"><label class="sr-only" for="scene-tea-draft">留下一句想法</label><div class="scene-compose-input-row"><textarea class="input" id="scene-tea-draft" rows="2" maxlength="600" placeholder="说说你的想法，或点麦克风输入……">${esc(t.draft)}</textarea><div class="scene-compose-buttons"><button class="scene-voice-button ${SCENE.voiceListening?'recording':''}" type="button" data-act="scene-voice" aria-label="${SCENE.voiceListening?'停止语音输入':'语音输入'}" aria-pressed="${!!SCENE.voiceListening}" ${!voice||SCENE.busy?'disabled':''} title="${voice?'浏览器语音识别；只填写草稿，不自动发送':'当前浏览器未提供语音识别，请直接输入文字'}">${uiIcon('mic',20)}<span>${SCENE.voiceListening?'停止':'语音'}</span></button><button id="scene-tea-send" class="btn btn-primary scene-chat-send" type="submit" aria-label="发送消息" ${SCENE.busy||!t.draft.trim()?'disabled':''}>${SCENE.busy?'回复中…':'发送'}${uiIcon('arrow',17)}</button></div></div><div class="scene-compose-caption"><span>Enter 发送 · Shift+Enter 换行</span><span>刷新后重置 · 作品请先下载</span></div><p id="scene-voice-status" class="scene-voice-status" role="status" aria-live="polite">${esc(SCENE.voiceMessage||'语音由浏览器识别，可能使用其联网服务；本应用不上传录音。')}</p><p id="scene-tea-request-hint" class="scene-chat-disclosure">${local?'本地引导不联网，不调用 AI。':(sceneChannel()==='private'?'仅发送当前私聊的文字与最近 8 条上下文；本页隔离演示，未接账号鉴权。':'仅发送当前群聊的文字与最近 8 条上下文；不读取私聊，不自动发布作品。')}</p></form></section></div>`;}
function sceneTeaSummaryHTML(){const t=sceneTeaState();return `<section class="scene-summary scene-chat-summary" aria-label="讨论收束草稿"><span class="studio-eyebrow">LEAVE SOMETHING USEFUL</span><h2>聊过的，不用散掉</h2><p>先整理、再修改。你确认后，才会留下有来源的灵感卡。</p>${t.summary?`<div class="scene-summary-points">${t.summary.points.map((p,i)=>`<label for="scene-summary-${i}">想法 ${i+1} · ${p.sourceIds.map(esc).join(' / ')}<textarea class="input" id="scene-summary-${i}" data-scene-summary="${i}" maxlength="300">${esc(p.text)}</textarea></label>`).join('')}${t.summary.questions?.length?`<p>待确认：${t.summary.questions.map(esc).join('；')}</p>`:''}</div>${sceneButton('scene-summary-save',t.saved?'已加入灵感池':sceneChannel()==='private'?'确认将摘要分享到公共灵感池':'确认加入灵感池',t.saved?'disabled':'',true)}${t.saved?sceneButton('scene-pool','去灵感池查看'):''}`:`<div class="scene-summary-empty"><span>01 说说感觉</span><span>02 看清不同方向</span><span>03 确认留下想法</span></div>`}${sceneButton('scene-go','带着想法去试图 →','data-page="look"')}</section>`;}

function scenePhotoInputHTML(target,photo){return `<label class="scene-upload" for="scene-${target}-photo">${uiIcon('upload',22)}<b>${photo?'更换照片':'选一张自己的照片'}</b><span>JPG / PNG / WebP · 最大 8 MB</span><input id="scene-${target}-photo" type="file" accept="image/jpeg,image/png,image/webp" data-scene-photo="${target}"></label>${photo?sceneMessage(photo.name+' · 原图保留在当前页面'):''}`;}
function sceneLookSVG(){return lookCollageSVG();}
function sceneHasLookPhoto(){const p=SCENE.look.photo;return !!(p&&SceneTools.imageSafe(p.url)&&p.width>0&&p.height>0);}
function sceneCropControlsHTML(){const l=SCENE.look,ready=sceneHasLookPhoto()&&!l.loading;return `<fieldset class="scene-photo-controls" id="scene-photo-controls" ${ready?'':'disabled'}><legend>${ready?'调整当前照片':'先选图，再调整照片'}</legend><div class="scene-crop">${[['x','左右位置',0,100],['y','上下位置',0,100],['zoom','照片缩放',50,200]].map(([key,label,min,max])=>`<label for="scene-look-${key}">${label}<output id="scene-value-${key}">${l[key]}${key==='zoom'?'%':''}</output><input id="scene-look-${key}" data-scene-crop="${key}" type="range" min="${min}" max="${max}" value="${l[key]}" ${ready?'':'disabled'}></label>`).join('')}</div><div class="scene-actions scene-crop-buttons">${sceneButton('scene-crop-step','↑ 上移','data-key="y" data-delta="-5" '+(ready?'':'disabled'))}${sceneButton('scene-crop-step','↓ 下移','data-key="y" data-delta="5" '+(ready?'':'disabled'))}${sceneButton('scene-crop-step','− 缩小','data-key="zoom" data-delta="-10" '+(ready?'':'disabled'))}${sceneButton('scene-crop-step','＋ 放大','data-key="zoom" data-delta="10" '+(ready?'':'disabled'))}${sceneButton('scene-crop-reset','取景复位',ready?'':'disabled')}</div></fieldset><p id="scene-photo-status" class="scene-photo-status" role="status">${l.loading?'正在读取所选图片，读完后即可调整。':ready?'正在调整：'+esc(l.photo.name)+'。拖动滑杆会立即改变上方照片。':'当前是版式占位图，还没有选中照片；此时位置和缩放不可用。'}</p>`;}
function sceneLookHTML(){const l=SCENE.look;const photos=S.pool.filter(p=>SceneTools.imageSafe(p.dataUrl));return `<div class="scene-editor-layout scene-look-layout"><section class="scene-paper scene-controls"><h2>把喜欢，放进画面</h2>${scenePhotoInputHTML('look',l.photo)}${photos.length?`<label for="scene-existing-photo">或引用本页已有原图<select id="scene-existing-photo" class="input"><option value="">请选择</option>${photos.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label>`:''}<label for="scene-look-title">标题<input id="scene-look-title" class="input" maxlength="24" value="${esc(l.title)}"></label><label for="scene-look-subtitle">补充一句<input id="scene-look-subtitle" class="input" maxlength="45" value="${esc(l.subtitle)}"></label><fieldset class="scene-layout-options"><legend>排版方式 · 三种固定排版 / 自由拼贴</legend>${[['frame','纪念相框','照片完整，像一张纪念卡'],['editorial','留白刊页','把文字和照片分开呼吸'],['panorama','横幅海报','上标题、中间横图、下说明'],['free','自由拼贴（不选排版）','主图、文字和素材都可拖动组合']].map(([key,title,sub])=>`<button data-act="scene-layout" data-layout="${key}" aria-pressed="${l.layout===key}"><b>${title}</b><small>${sub}</small></button>`).join('')}</fieldset>${l.layout==='free'?'':sceneCropControlsHTML()}${lookCollageControls()}<details class="scene-ai-details"><summary>@ AI · 看看这张图</summary><label for="scene-look-goal">想让助手看什么？<textarea id="scene-look-goal" class="input" maxlength="1000">${esc(l.goal)}</textarea></label>${sceneToolsHTML(true)}${sceneButton('scene-look-ai',SCENE.busy?'正在处理…':'@AI 助手，看看这张图',SCENE.busy?'disabled':'')}<p id="scene-look-reply" class="scene-reply">${esc(l.reply||'选好图后点击 @AI 助手，直接看看当前预览。')}</p></details></section><section class="scene-preview-column"><div class="scene-preview-label"><span>实时排版 · 原图不覆盖</span><span>600 × 800</span></div><div id="scene-look-preview" class="scene-art">${sceneLookSVG()}</div><div class="scene-actions">${sceneButton('scene-look-save',l.saved?'已留下一版':'确认留为稿件',!sceneHasLookContent()||l.saved?'disabled':'',true)}${sceneButton('scene-download','下载预览 SVG','data-target="look" '+(sceneHasLookContent()?'':'disabled'))}${sceneButton('scene-to-decision','带到决策间 →',!l.saved?'disabled':'')}</div><p id="scene-look-receipt" class="scene-caption">${!sceneHasLookContent()?'选择主照片或导入素材，即可开始拼贴。':l.saved?'新稿已进入评审，可到决策间继续加减。':'照片已加载，确认后才会加入稿件；原图不会被修改。'}</p></section></div>`;}


function sceneJoinHTML(){const j=SCENE.join;return `<div class="scene-editor-layout"><section class="scene-paper scene-controls"><span class="studio-eyebrow">A SMALL THING, TOGETHER</span><h2>不用会设计，也能留一笔</h2><p>照片和祝福选一个，或者两个都留下。</p>${scenePhotoInputHTML('join',j.photo)}${puzzleControls()}<label for="scene-join-text">送上一句祝福<textarea id="scene-join-text" class="input" maxlength="24">${esc(j.text)}</textarea></label><fieldset class="scene-stickers"><legend>选一个陪你出场的小元素</legend>${[['star','星星'],['flower','小花'],['turtle','小龟'],['ribbon','丝带']].map(([key,label])=>`<button data-act="scene-sticker" data-sticker="${key}" aria-pressed="${j.sticker===key}" aria-label="${label}"><svg viewBox="-65 -65 130 130" aria-hidden="true">${window.XDPRemix.sticker(key,'#9875B6')}</svg><span>${label}</span></button>`).join('')}</fieldset>${sceneButton('scene-join-save',j.saved?'这份心意已留下':'确认留下我的心意',j.saved?'disabled':'',true)}<p id="scene-join-receipt" class="scene-caption">${j.saved?'已署名加入灵感池；同一份贡献不会重复计数。':'预览不等于投稿，确认后才会留下。'}</p><div class="scene-rapport"><span>${uiIcon('heart')} 共创默契</span><b id="scene-rapport-count">${j.count}</b><p>仅记录你在本页留下的贡献，不代表与明星的真实亲密度。</p></div></section><section class="scene-preview-column"><div class="scene-preview-label"><span>这是你留下的一小份喜欢</span><span>本机预览</span></div><div id="scene-join-preview" class="scene-art">${sceneJoinSVG()}</div><div class="scene-actions">${sceneButton('scene-download','下载预览 SVG','data-target="join"')}${sceneButton('scene-pool','看看大家的灵感')}</div></section></div>`;}
function sceneDecisionBase(){return S.arts.find(a=>a.id===SCENE.decision.id);}
function sceneSelectArt(id){const d=SCENE.decision;d.reviewDrafts=d.reviewDrafts||{};if(d.id)d.reviewDrafts[d.id]=d.reviewDraft||'';const a=S.arts.find(a=>a.id===id);if(!a)return;const baseSvg=artSVG(a).replaceAll('<!--SCENE-EXTRAS-->','<!--SAVED-EXTRAS-->').replaceAll('<!--/SCENE-EXTRAS-->','<!--/SAVED-EXTRAS-->');Object.assign(SCENE.decision,{id,reviewDraft:d.reviewDrafts[id]||'',svg:baseSvg,baseSvg,layers:[],view:'after',revision:SCENE.decision.revision+1,bingo:false,saved:null,changed:false,note:'先选一个变量，试着加一点或减一点。'});}
function sceneDecisionHTML(){const d=SCENE.decision;if(!sceneDecisionBase()&&S.arts.length)sceneSelectArt(S.arts[0].id);const a=sceneDecisionBase();return `<div class="scene-editor-layout"><section class="scene-paper scene-controls"><h2>这次，只改一个地方</h2><p>先看差别，再说 Bingo。原稿始终保留。</p><label for="scene-decision-art">选择要比较的稿件<select class="input" id="scene-decision-art">${S.arts.map(a=>`<option value="${esc(a.id)}" ${a.id===d.id?'selected':''}>${esc(a.id)} · ${esc(P(a.author).name)} · ${esc(a.note||'未命名稿件').slice(0,45)}</option>`).join('')}</select></label>${a?'':sceneMessage('还没有稿件，先去看图共创留下一版。')}<fieldset class="scene-layout-options"><legend>本次只动这个变量</legend>${[['title','标题大小'],['decoration','边角贴纸']].map(([key,label])=>`<button data-act="scene-variable" data-kind="${key}" aria-pressed="${d.kind===key}">${label}</button>`).join('')}</fieldset><div class="scene-actions">${sceneButton('scene-adjust','− 少一点','data-delta="-1" '+(!a?'disabled':''))}${sceneButton('scene-adjust','＋ 多一点','data-delta="1" '+(!a?'disabled':''))}${sceneButton('scene-reset','恢复原稿',!a?'disabled':'')}</div><p id="scene-decision-note" class="scene-caption">${esc(d.note)}</p><div class="scene-bingo-steps"><span>01 先确认方向</span>${sceneButton('scene-direction',d.bingo?'方向已确认 ✓':'这个方向 Bingo',!d.changed||d.bingo?'disabled':'')}<span>02 再另存新版本</span>${sceneButton('scene-decision-save',d.saved?'已另存新版本':'Bingo，留这一版',!d.bingo||d.saved?'disabled':'',true)}</div>${sceneMessage('方向确认不会自动保存，也不会替主办定稿。')}<h3>本页留版记录</h3><ol class="scene-version-history">${d.history.length?d.history.map(h=>`<li><b>${esc(h.id)}</b><p>${esc(h.note)}</p><small>来自 ${esc(h.from)} · ${esc(P(h.by).name)}</small></li>`).join(''):'<li>还没有新版本。</li>'}</ol></section><section class="scene-preview-column"><div class="scene-compare"><button data-act="scene-compare" data-view="before" aria-pressed="${d.view==='before'}">原稿</button><button data-act="scene-compare" data-view="after" aria-pressed="${d.view==='after'}">修改后</button></div><div id="scene-decision-preview" class="scene-art">${a?(d.view==='before'?d.baseSvg:d.svg):SceneTools.photoSVG(null)}</div><div class="scene-actions">${sceneButton('scene-download','下载当前预览','data-target="decision" '+(!a?'disabled':''))}${sceneButton('scene-open-remix','进入完整二创',!a?'disabled':'')}</div>${sceneReviewHTML()}</section></div>`;}
function sceneResourcesHTML(){return `<div class="scene-resource-grid">${[['pool','灵感池','大家留下的想法和参考',S.pool.length],['templates','选一套模板','保留六套原创版式','6'],['assistant','设计助手','文字起稿、上传与语音',''],['done','稿件评审','查看署名、反馈与原有投票流程',S.arts.length],['discussion','历史讨论','保留原文，不伪造新群聊',''],['home','项目概览','规则与项目进度','']].map(([key,title,sub,count])=>`<button data-act="scene-resource" data-resource="${key}"><span class="studio-eyebrow">${count!==''?count+' / ITEMS':'WORKSPACE'}</span><h2>${title}</h2><p>${sub}</p><span>打开 ${uiIcon('arrow')}</span></button>`).join('')}</div>`;}
function sceneSync(){const n=$('#scene-error');if(n)n.textContent=SCENE.error;const notice=$('#scene-notice');if(notice)notice.textContent=SCENE.notice;const local=SCENE.engine==='local',label=$('#scene-engine-label'),note=$('#scene-engine-note'),tea=$('#scene-tea-engine-label'),send=$('#scene-tea-send'),hint=$('#scene-tea-request-hint');if(hint)hint.textContent=local?'本地引导不联网，不调用 AI。':(sceneChannel()==='private'?'仅发送当前私聊与最近 8 条上下文；本页隔离演示，未接账号鉴权。':'仅发送当前群聊与最近 8 条上下文；不读取私聊，不自动发布作品。');if(label)label.textContent=local?'本地规则引导 · 非 AI 分析':'银河智算 · 在线 AI';if(note)note.textContent=local?'本地模式不会发送文字或图片，不联网检索；可继续排版、保存和下载。':(note.dataset.images==='1'?'点击 @AI 助手，即发送':'点击发送，即发送')+(note.dataset.images==='1'?'当前问题和预览图片':'当前问题与最近 8 条对话')+'给银河智算；先逐步确认想法；只有点击找参考才会检索。';if(tea)tea.textContent=local?'阿浣 · 本地引导':'阿浣 · AI 灵感搭子';if(send){send.disabled=SCENE.busy||!sceneTeaState().draft.trim();send.textContent=SCENE.busy?'回复中…':'发送';}const refs=$('[data-act="scene-guide-references"]');if(refs){refs.disabled=SCENE.busy||local;refs.textContent=local?'在线模式可找图片参考':'按这个方向找图片参考';}sceneVoiceSync();}
function sceneVoiceSync(){const button=$('[data-act="scene-voice"]'),status=$('#scene-voice-status');if(button){const available=window.XDPVoice?.available()===true;button.disabled=SCENE.busy||!available;button.setAttribute?.('aria-pressed',String(!!SCENE.voiceListening));button.setAttribute?.('aria-label',SCENE.voiceListening?'停止语音输入':'语音输入');const text=button.querySelector?.('span');if(text)text.textContent=SCENE.voiceListening?'停止':'语音';}if(status)status.textContent=SCENE.voiceMessage||(window.XDPVoice?.available()?'语音由浏览器识别，可能使用其联网服务；本应用不上传录音。':'当前浏览器未提供语音识别，请直接输入文字。');}
function sceneStartVoice(){const t=sceneTeaState(),actor=ME,channel=sceneChannel(),browser=window.XDPVoice?.browser;if(!browser||SCENE.busy)return;if(browser.isListening()){browser.stop();return;}browser.start({getText:()=>t.draft,onText:text=>{if(ME!==actor||sceneChannel()!==channel||sceneTeaState()!==t){browser.cancel();return;}t.draft=text;const field=$('#scene-tea-draft');if(field)field.value=text;sceneSync();},onState:value=>{SCENE.voiceListening=value;sceneVoiceSync();},onStatus:message=>{SCENE.voiceMessage=message;sceneVoiceSync();},maxLength:600});}
function sceneDirty(target){const s=SCENE[target];s.revision++;s.saved=null;SCENE.textConsent=false;SCENE.imageConsent=false;SCENE.error='';if(target==='look')s.reply=null;sceneSync();}
function sceneUpdatePreview(target,cropOnly=false){
 const p=$('#scene-'+target+'-preview'),l=SCENE.look,image=target==='look'?p?.querySelector?.('[data-scene-image]'):null;
 if(p){if(cropOnly&&l.layout!=='free'&&image&&l.photo){const g=SceneTools.photoPlacement(l.photo,l);for(const [key,val] of Object.entries({x:g.x,y:g.y,width:g.width,height:g.height}))image.setAttribute(key,String(val));}else p.innerHTML=target==='look'?sceneLookSVG():sceneJoinSVG();}
 const save=$('[data-act="scene-'+target+'-save"]');if(save){save.disabled=SCENE.busy||!!SCENE[target].saved||(target==='look'?!sceneHasLookContent():!SCENE.join.photo&&!SCENE.join.text.trim());save.textContent=target==='look'?'确认留为稿件':'确认留下我的心意';}
 const receipt=$('#scene-'+target+'-receipt');if(receipt)receipt.textContent='预览已更新，确认后才会留下新版本。';if(target==='look'){const onward=$('[data-act="scene-to-decision"]');if(onward)onward.disabled=!l.saved;const reply=$('#scene-look-reply');if(reply)reply.textContent='画面已更改，点击 @AI 助手获取新建议。';}
}
async function sceneRequest(mode,goal,image,extra={}){const t=sceneTeaState(),g=sceneGuide(t);const response=await fetch('/api/scenes/reply',{method:'POST',headers:{'Content-Type':'application/json'},signal:AbortSignal.timeout(165000),body:JSON.stringify({mode,goal,topic:t.topic,channel:sceneChannel(),messages:mode==='tea'||mode==='summary'?t.messages.slice(-8):[],guidance:{...g,...extra},consent:true,imageConsent:!!image,image})});let data;try{data=await response.json();}catch{throw Error('未连接共创接口。请用本机服务打开，或切换到本地引导。');}if(!response.ok)throw Error(data.error||'服务不可用，内容仍保留。');if(!data.reply&&!data.suggestion&&!data.points?.length)throw Error('服务未返回有效建议。');return data;}

async function sceneTask(fn){if(SCENE.busy)return;SCENE.busy=true;SCENE.error='';SCENE.notice='';paintScene();try{await fn();}catch(e){SCENE.error=e.name==='TimeoutError'?'请求超时，原内容仍保留，请手动重试。':e.message;}finally{SCENE.busy=false;SCENE.textConsent=false;SCENE.imageConsent=false;paintStudioShell();if(sceneName()||WORK.page==='resources')paintScene();}}
async function sceneSendTea(){window.XDPVoice?.cancel();const t=sceneTeaState(),text=t.draft.trim();if(!text){SCENE.error='先写一句想法再发送。';sceneSync();return;}const link=t.link.trim()?SceneTools.safeLink(t.link):null;if(t.link.trim()&&!link){SCENE.error='来源链接需为不含账号密码的 HTTPS 地址。';sceneSync();return;}await sceneTask(async()=>{const id=sceneId('M'),actor=ME;t.messages.push({id,role:'user',by:actor,text,link});t.draft='';t.link='';t.summary=null;t.saved=null;const rev=++t.revision,engine=SCENE.engine,g=sceneGuide(t);if(g.audience){g.sourceIds=g.sourceIds||[];g.sourceIds.push(id);}const question=SceneTools.guideAdvance(g,text);if(WORK.page==='tea')paintScene();let reply=question;if(engine==='online'&&g.audience){const r=await sceneRequest('tea',text,null,{nextQuestion:question});reply=r.reply||r.suggestion||question;}if(t.revision===rev)t.messages.push({id:sceneId('AI'),role:'assistant',text:reply,engine:g.audience?engine:'local'});});}

async function sceneMakeSummary(){const t=sceneTeaState();if(!t.messages.some(m=>m.role==='user'))return;await sceneTask(async()=>{const rev=t.revision;const result=SCENE.engine==='local'?{points:SceneTools.summary(t.messages),questions:[]}:await sceneRequest('summary','整理成员想法，保留分歧与来源');if(t.revision===rev){t.summary=result;t.saved=null;}});}
function sceneSaveSummary(){const t=sceneTeaState();if(!t.summary||t.saved)return;const points=t.summary.points.filter(p=>p.text.trim());if(!points.length){SCENE.error='至少保留一条非空想法。';sceneSync();return;}const id=sceneId('P');S.pool.unshift({id,name:'茶话收束 · '+(TeaScripts.scenario(t.topic).label),note:points.map(p=>p.text).join('；'),by:ME,cat:'copy',kind:'insp',likes:[],cmts:[],taken:false,sourceIds:[...new Set(points.flatMap(p=>p.sourceIds))],sceneSummary:JSON.parse(JSON.stringify(t.summary))});t.saved=id;SCENE.notice='已加入灵感池，保留消息来源；这不代表全体成员共识。';paintStudioShell();paintScene();}
async function sceneLoadPhoto(file,target){if(!file)return;const error=uploadFileError(file);if(error){SCENE.error=error;sceneSync();return;}const revision=(SCENE[target].uploadToken||0)+1;SCENE[target].uploadToken=revision;SCENE[target].loading=true;SCENE.error='';if(WORK.page===target)paintScene();else sceneSync();try{const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('读取失败，请重新选择。'));r.readAsDataURL(file);});const img=await sceneDecode(url);if(img.width*img.height>60000000)throw Error('图片像素过大，请先缩小到 6000 万像素以内。');if(revision!==SCENE[target].uploadToken)return;SCENE[target].photo={url,name:file.name,width:img.width,height:img.height};SCENE[target].loading=false;if(target==='look'){SCENE.look.x=50;SCENE.look.y=50;SCENE.look.zoom=100;}sceneDirty(target);if(WORK.page===target)paintScene();}catch(e){if(revision!==SCENE[target].uploadToken)return;SCENE[target].loading=false;SCENE.error='图片无法读取：'+e.message;if(WORK.page===target)paintScene();else sceneSync();}}
function sceneDecode(url){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('不是有效图片或浏览器不支持。'));i.src=url;});}
async function sceneRaster(svg){const image=await sceneDecode('data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)),canvas=document.createElement('canvas');canvas.width=600;canvas.height=800;canvas.getContext('2d').drawImage(image,0,0,600,800);return canvas.toDataURL('image/png');}
function sceneCollageSources(){return [SCENE.look.photo,...lookCollage().materials].filter(m=>m?.sourcePoolId).map(m=>({id:m.sourcePoolId,by:m.sourceBy,name:m.name}));}
function sceneSaveLook(){const l=SCENE.look;if(!sceneHasLookContent()||l.saved)return;const id=sceneId('A');S.arts.unshift({id,author:ME,note:l.title||'看图共创新稿',up:true,likes:[],kw:['看图共创','本机排版'],posterKey:'lilac-photo',draftSvg:sceneLookSVG(),sceneComposed:true,sourceIds:[...new Set(sceneCollageSources().map(m=>m.id))],contributors:[...new Set(sceneCollageSources().map(m=>m.by).filter(Boolean))],sourcePhotoName:l.photo?.name||'拼贴素材',collageState:JSON.parse(JSON.stringify(lookCollage()))});S.artPos[id]={x:30,y:30};l.saved=id;sceneAwardQuest('collage',id);for(const m of [l.photo,...lookCollage().materials].filter(Boolean)){const source=S.pool.find(p=>p.id===m.sourcePoolId&&p.dataUrl===m.url);if(source)source.taken=true;}SCENE.notice='已另存一份署名新稿，原图保持不变。';paintStudioShell();paintScene();}
function sceneSaveJoin(){const j=SCENE.join;if(j.saved||(!j.photo&&!j.text.trim()))return;j.contributions=j.contributions||[];const composition=JSON.stringify(puzzleState());const previous=j.contributions.find(c=>c.text===j.text.trim()&&c.sticker===j.sticker&&c.url===(j.photo?.url||'')&&c.composition===composition);if(previous){j.saved=previous.id;SCENE.notice='这份心意已经留下，不重复增加共创默契。';paintScene();return;}const id=sceneId('P');S.pool.unshift({id,name:'一份心意 · '+P(ME).name,note:j.text,by:ME,cat:'visual',kind:'up',likes:[],cmts:[],taken:false,draftSvg:sceneJoinSVG(),sceneContribution:true,...(j.photo?{dataUrl:j.photo.url,width:j.photo.width,height:j.photo.height}:{}),sticker:j.sticker});j.saved=id;j.count++;j.contributions.push({id,text:j.text.trim(),sticker:j.sticker,url:j.photo?.url||'',composition});SCENE.notice='心意已留下 · 共创默契 +1';paintStudioShell();paintScene();}
function sceneAdjust(delta){const d=SCENE.decision,a=sceneDecisionBase();if(!a)return;const next=SceneTools.revise(d.svg,d.kind,delta,d.layers,window.XDPRemix.sticker);d.svg=next.svg;d.layers=next.layers;d.note=next.note;d.changed=d.svg!==d.baseSvg;d.bingo=false;d.saved=null;d.view='after';d.revision++;sceneUpdateDecision();}

function sceneUpdateDecision(){const d=SCENE.decision,preview=$('#scene-decision-preview');if(preview)preview.innerHTML=d.view==='before'?d.baseSvg:d.svg;const note=$('#scene-decision-note');if(note)note.textContent=d.note;for(const [act,disabled,text] of [['scene-direction',!d.changed||d.bingo,d.bingo?'方向已确认 ✓':'这个方向 Bingo'],['scene-decision-save',!d.bingo||!!d.saved,d.saved?'已另存新版本':'Bingo，留这一版']]){const b=$('[data-act="'+act+'"]');if(b){b.disabled=disabled;b.textContent=text;}}for(const act of ['scene-variable','scene-compare'])document.querySelectorAll('[data-act="'+act+'"]').forEach(b=>b.setAttribute('aria-pressed',String(act==='scene-variable'?b.dataset.kind===d.kind:b.dataset.view===d.view)));}
function sceneSaveDecision(){const d=SCENE.decision,a=sceneDecisionBase();if(!a||!d.bingo||d.saved||!d.changed)return;const id=sceneId('A');S.arts.unshift({id,author:ME,note:'Bingo · '+d.note,up:true,likes:[],kw:['Bingo 留版'],draftSvg:d.svg,posterKey:a.posterKey,sceneComposed:true,from:{id:a.id,by:a.author,remix:true}});S.artPos[id]={x:30,y:30};d.saved=id;d.history.unshift({id,from:a.id,note:d.note,by:ME});SCENE.notice='新版本已进入稿件评审，原作者与原稿保持不变；尚未主办定稿。';paintStudioShell();paintScene();}
function sceneOpenResource(key){SCENE.error='';if(['assistant','discussion'].includes(key)){workEnter(key);return;}if(key==='templates'){openSubmit('tpl');return;}WORK.page=null;clearWorkOverlays();S.stage=key==='home'?1:2;S.boardView=key==='home'?'pool':key;render();}

// Positions use the SVG's 600 × 800 coordinate space, independent of display size.
function puzzleState(){const j=SCENE.join;if(!j.puzzle)j.puzzle={fontSize:34,frame:'classic',photo:{x:60,y:100},title:{x:56,y:637},sticker:{x:510,y:710}};return j.puzzle;}
function puzzleControls(){const p=puzzleState();return `<fieldset class="scene-layout-options"><legend>固定边框款式</legend>${[['classic','纪念相框'],['double','双线相框'],['rounded','圆角相框']].map(([id,name])=>`<button data-puzzle-frame="${id}" aria-pressed="${p.frame===id}">${name}</button>`).join('')}</fieldset><label for="puzzle-font">祝福字号 <output id="puzzle-font-value">${p.fontSize}</output><input id="puzzle-font" type="range" min="18" max="64" step="1" value="${p.fontSize}"></label><p class="scene-caption">直接拖动画框内的照片、祝福和小元素调整位置。也可选中后用方向键微调。</p>`;}
function sceneJoinSVG(){
 const j=SCENE.join,p=puzzleState(),E=esc;
 const frame=p.frame==='rounded'?{r:30,stroke:'#BCA8D1',width:8}:p.frame==='double'?{r:4,stroke:'#9875B6',width:3}:{r:4,stroke:'#FFFCF6',width:16};
 const photo=j.photo,valid=photo&&SceneTools.imageSafe(photo.url),w=480,h=480,scale=photo?Math.max(w/photo.width,h/photo.height):1,iw=photo?photo.width*scale:w,ih=photo?photo.height*scale:h;
 const lines=Array.from(j.text||'一起留下喜欢'),perLine=Math.max(1,Math.floor(488/(p.fontSize*1.02))),rows=[];for(let i=0;i<lines.length;i+=perLine)rows.push(lines.slice(i,i+perLine).join(''));
 const layer=(key,label,body)=>`<g data-puzzle-layer="${key}" tabindex="0" role="button" aria-label="拖动${label}，方向键微调" transform="translate(${p[key].x} ${p[key].y})">${body}</g>`;
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 800" role="img" aria-label="极简拼图预览"><defs><clipPath id="puzzle-photo-clip"><rect width="480" height="480" rx="${frame.r}"/></clipPath></defs><rect width="600" height="800" fill="#E9E0F4"/><circle cx="590" cy="90" r="170" fill="#F2DDEB"/><path d="M0 710Q300 570 600 720V800H0Z" fill="#DAE8F2"/><text x="44" y="48" font-family="sans-serif" font-size="13" fill="#665277" letter-spacing="3">XINGDONGPAI / OUR LITTLE MOMENT</text>${layer('photo','照片',`<rect x="-10" y="-10" width="500" height="500" rx="${frame.r+8}" fill="#FFFCF6"/><g clip-path="url(#puzzle-photo-clip)">${valid?`<image href="${E(photo.url)}" x="${(w-iw)/2}" y="${(h-ih)/2}" width="${iw}" height="${ih}"/>`:`<rect width="480" height="480" fill="#D4C3E5"/><text x="240" y="240" text-anchor="middle" font-size="19" fill="#665277">${photo?'照片无法显示':'上传你的照片'}</text>`}</g><rect width="480" height="480" rx="${frame.r}" fill="none" stroke="${frame.stroke}" stroke-width="${frame.width}"/>${p.frame==='double'?'<rect x="-7" y="-7" width="494" height="494" rx="6" fill="none" stroke="#9875B6" stroke-width="2"/>':''}`)}${layer('title','祝福文字',`<rect x="-4" y="${-p.fontSize}" width="${Math.min(500,Math.max(...rows.map(r=>Array.from(r).length))*p.fontSize+8)}" height="${rows.length*p.fontSize*1.2+8}" fill="transparent"/>${rows.map((line,i)=>`<text y="${i*p.fontSize*1.2}" font-family="sans-serif" font-weight="700" font-size="${p.fontSize}" fill="#59426F">${E(line)}</text>`).join('')}`)}<text x="48" y="750" font-family="sans-serif" font-size="17" fill="#756184">一张照片，一句祝福 · ${E(P(ME).name)}</text>${layer('sticker','小元素',`<g transform="scale(.65)">${window.XDPRemix.sticker(j.sticker,'#9875B6')}</g>`)}<text x="44" y="777" font-family="sans-serif" font-size="11" fill="#756184">CO-CREATION / 照片与文字由参与者提供</text></svg>`;
}
function puzzleClamp(node,key,x,y){const b=node.getBBox();return {x:Math.max(-b.x,Math.min(600-b.x-b.width,x)),y:Math.max(-b.y,Math.min(800-b.y-b.height,y))};}
function puzzleMove(node,key,x,y){const pos=puzzleClamp(node,key,x,y);Object.assign(puzzleState()[key],pos);node.setAttribute('transform',`translate(${pos.x} ${pos.y})`);}
function puzzleChanged(){sceneDirty('join');sceneUpdatePreview('join');}
document.addEventListener('input',e=>{if(e.target.id!=='puzzle-font')return;puzzleState().fontSize=Number(e.target.value);document.getElementById('puzzle-font-value').textContent=e.target.value;puzzleChanged();const n=document.querySelector('#scene-join-preview [data-puzzle-layer="title"]');if(n){const p=puzzleState().title;puzzleMove(n,'title',p.x,p.y);}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-puzzle-frame]');if(!b)return;puzzleState().frame=b.dataset.puzzleFrame;document.querySelectorAll('[data-puzzle-frame]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));puzzleChanged();});
document.addEventListener('pointerdown',e=>{
 const node=e.target.closest('#scene-join-preview [data-puzzle-layer]');if(!node||e.button!==0)return;e.preventDefault();node.focus();const svg=node.ownerSVGElement,key=node.dataset.puzzleLayer,p=puzzleState()[key],initial={...p},matrix=svg.getScreenCTM()?.inverse();if(!matrix)return;const point=(x,y)=>new DOMPoint(x,y).matrixTransform(matrix),start=point(e.clientX,e.clientY);let moved=false;node.setPointerCapture(e.pointerId);
 const move=ev=>{if(ev.pointerId!==e.pointerId)return;const v=point(ev.clientX,ev.clientY);moved=true;puzzleMove(node,key,initial.x+v.x-start.x,initial.y+v.y-start.y);};
 const end=ev=>{if(ev.pointerId!==e.pointerId)return;node.removeEventListener('pointermove',move);node.removeEventListener('pointerup',end);node.removeEventListener('pointercancel',end);if(node.hasPointerCapture(e.pointerId))node.releasePointerCapture(e.pointerId);if(moved){puzzleChanged();document.querySelector(`#scene-join-preview [data-puzzle-layer="${key}"]`)?.focus({preventScroll:true});}};
 node.addEventListener('pointermove',move);node.addEventListener('pointerup',end);node.addEventListener('pointercancel',end);
});
document.addEventListener('keydown',e=>{const node=e.target.closest('#scene-join-preview [data-puzzle-layer]'),delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(!node||!delta)return;e.preventDefault();const key=node.dataset.puzzleLayer,p=puzzleState()[key],step=e.shiftKey?10:2;puzzleMove(node,key,p.x+delta[0]*step,p.y+delta[1]*step);puzzleChanged();document.querySelector(`#scene-join-preview [data-puzzle-layer="${key}"]`)?.focus({preventScroll:true});});

// Look editor state is kept independently from the selected fixed layout.
function lookCollage(){const l=SCENE.look;if(!l.collage)l.collage={materials:[],selected:'photo',titleSize:34,subtitleSize:17,photo:{x:300,y:360,scale:100,angle:0},title:{x:56,y:637},subtitle:{x:48,y:714}};return l.collage;}
function sceneHasLookContent(){return sceneHasLookPhoto()||lookCollage().materials.length>0;}
function lookSelected(){const c=lookCollage();return c.selected==='photo'?c.photo:c.materials.find(m=>m.id===c.selected);}
function lookCollageControls(){const c=lookCollage(),s=lookSelected(),free=SCENE.look.layout==='free';return `<section class="look-collage-tools"><h3>加入素材</h3><label class="scene-upload" for="look-material-files">${uiIcon('upload',22)}<b>导入拼贴素材</b><span>可多选 JPG / PNG / WebP，透明 PNG 保留透明背景</span><input id="look-material-files" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><label for="look-layer-select">选择要调整的图片<select id="look-layer-select" class="input"><option value="photo" ${c.selected==='photo'?'selected':''}>主照片${free?'':'（固定取景）'}</option>${c.materials.map((m,i)=>`<option value="${esc(m.id)}" ${m.id===c.selected?'selected':''}>${i+1}. ${esc(m.name)}</option>`).join('')}</select></label><fieldset ${!s||(c.selected==='photo'&&!free)?'disabled':''}><legend>素材大小与角度</legend>${[['scale','大小',20,250,'%'],['angle','旋转',-180,180,'°']].map(([key,label,min,max,unit])=>`<label for="look-layer-${key}">${label}<output id="look-layer-${key}-value">${s?.[key]??(key==='scale'?100:0)}${unit}</output><input id="look-layer-${key}" type="range" min="${min}" max="${max}" value="${s?.[key]??(key==='scale'?100:0)}"></label>`).join('')}<details class="scene-layer-crop"><summary>只取这张图的一部分</summary>${[['cropW','取用宽度',10,100],['cropH','取用高度',10,100],['cropX','左右取景',0,100],['cropY','上下取景',0,100]].map(([key,label,min,max])=>`<label for="look-layer-${key}">${label}<input id="look-layer-${key}" type="range" min="${min}" max="${max}" value="${s?.[key]??(key==='cropW'||key==='cropH'?100:50)}"></label>`).join('')}<p class="scene-caption">矩形取景，不等同于自动抠图；每张原图保持不变。</p></details><div class="scene-actions"><button type="button" class="btn" data-look-action="front">移到最上层</button><button type="button" class="btn" data-look-action="remove" ${c.selected==='photo'?'disabled':''}>移除素材</button></div></fieldset><p class="scene-caption">${free?'自由拼贴：拖动照片、素材和文字组合画面。':'固定排版保留主图取景；导入的素材仍可自由拖动、旋转和缩放。选择自由拼贴可移动主图和文字。'}</p><h3>文字大小</h3>${[['titleSize','标题字号',18,72],['subtitleSize','补充文字字号',12,40]].map(([key,label,min,max])=>`<label for="look-${key}">${label}<output id="look-${key}-value">${c[key]}</output><input id="look-${key}" type="range" min="${min}" max="${max}" value="${c[key]}"></label>`).join('')}</section>`;}
function lookLayerSVG(item,id){const clamp=(v,f,min,max)=>Math.max(min,Math.min(max,Number.isFinite(Number(v))?Number(v):f)),cw=item.width*clamp(item.cropW,100,10,100)/100,ch=item.height*clamp(item.cropH,100,10,100)/100,cx=(item.width-cw)*clamp(item.cropX,50,0,100)/100,cy=(item.height-ch)*clamp(item.cropY,50,0,100)/100,w=280,h=280*ch/cw,scale=item.scale/100;return `<g data-look-layer="${esc(id)}" tabindex="0" role="button" aria-label="拖动${esc(item.name||'主照片')}，方向键微调" transform="translate(${item.x} ${item.y}) rotate(${item.angle}) scale(${scale})"><svg x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" viewBox="${cx} ${cy} ${cw} ${ch}" overflow="hidden"><image href="${esc(item.url)}" width="${item.width}" height="${item.height}"/></svg></g>`;}

function lookTextSVG(key,text,size,x,y,maxWidth,free){const chars=Array.from(text||''),count=Math.max(1,Math.floor(maxWidth/size)),rows=[];for(let i=0;i<chars.length;i+=count)rows.push(chars.slice(i,i+count).join(''));return `<g data-scene-${key}="true" ${free?`data-look-layer="${key}" tabindex="0" role="button" aria-label="拖动${key==='title'?'标题':'补充文字'}，方向键微调"`:''} ${free?`transform="translate(${x} ${y})"`:""}>${rows.map((line,i)=>`<text x="${free?0:x}" y="${(free?0:y)+i*size*1.25}" font-family="sans-serif" font-size="${size}" fill="${key==='title'?'#59426F':'#756184'}" ${key==='title'?'font-weight="700"':''}>${esc(line)}</text>`).join('')}</g>`;}
function lookCollageSVG(){const l=SCENE.look,c=lookCollage(),free=l.layout==='free';let svg;
 if(free){svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 800" role="img" aria-label="自由拼贴预览"><rect width="600" height="800" fill="#E9E0F4"/><circle cx="590" cy="90" r="170" fill="#F2DDEB"/><path d="M0 710Q300 570 600 720V800H0Z" fill="#DAE8F2"/>${sceneHasLookPhoto()?lookLayerSVG({...l.photo,...c.photo},'photo'):''}<g data-scene-title="true"></g><g data-scene-subtitle="true"></g></svg>`;
 }else svg=SceneTools.photoSVG(l.photo,l);
 const editorial=l.layout==='editorial',panorama=l.layout==='panorama';
 const tx=free?c.title.x:editorial?44:56,ty=free?c.title.y:editorial?145:panorama?116:637;
 const sx=free?c.subtitle.x:48,sy=free?c.subtitle.y:panorama?650:714;
 svg=svg.replace(/<g data-scene-title="true">[\s\S]*?<\/g>/,()=>lookTextSVG('title',l.title,c.titleSize,tx,ty,editorial?150:488,free));
 svg=svg.replace(/<g data-scene-subtitle="true">[\s\S]*?<\/g>/,()=>lookTextSVG('subtitle',l.subtitle,c.subtitleSize,sx,sy,500,free));
 svg=svg.replace(/data-scene-(title|subtitle)="true"\s+>/g,'data-scene-$1="true">');return svg.replace('</svg>',c.materials.map(m=>lookLayerSVG(m,m.id)).join('')+'<metadata id="collage-sources">'+esc(JSON.stringify(sceneCollageSources()))+'</metadata></svg>');
}
function lookRefresh(){sceneDirty('look');sceneUpdatePreview('look');const b=document.querySelector('[data-act="scene-download"][data-target="look"]');if(b)b.disabled=!sceneHasLookContent();}
async function lookImportMaterials(files){const c=lookCollage();if(c.importing)return;c.importing=true;SCENE.error='';let added=0;const errors=[];try{for(const file of files){if(c.materials.length>=16){errors.push('最多可加入 16 份素材。');break;}const error=uploadFileError(file);if(error){errors.push(file.name+'：'+error);continue;}try{const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('读取失败'));r.readAsDataURL(file);});const image=await sceneDecode(url);if(image.width*image.height>60000000)throw Error('图片像素过大');const id=sceneId('material');c.materials.push({id,name:file.name,url,width:image.width,height:image.height,x:300+(added%3)*25,y:350+(added%3)*25,scale:100,angle:0});c.selected=id;added++;}catch(e){errors.push(file.name+'：'+e.message);}}}finally{c.importing=false;if(added)sceneDirty('look');SCENE.error=errors.join('；');if(WORK.page==='look')paintScene();}}
document.addEventListener('change',e=>{if(e.target.dataset?.poolCollage){const id=e.target.dataset.poolCollage,p=S.pool.find(p=>p.id===id);if(p&&SceneTools.imageSafe(p.dataUrl)){if(e.target.checked)SCENE.poolSelected.add(id);else SCENE.poolSelected.delete(id);scenePoolSelectionSync();}}if(e.target.id==='scene-guide-rights'){sceneGuide().rights=['granted','explore'].includes(e.target.value)?e.target.value:'pending';}if(e.target.id==='look-material-files')lookImportMaterials(Array.from(e.target.files||[]));if(e.target.id==='look-layer-select'){lookCollage().selected=e.target.value;paintScene();}});
document.addEventListener('input',e=>{const id=e.target.id,c=SCENE.look.collage;if(!c)return;const sizeKey=id==='look-titleSize'?'titleSize':id==='look-subtitleSize'?'subtitleSize':null;const property=id==='look-layer-scale'?'scale':id==='look-layer-angle'?'angle':['cropW','cropH','cropX','cropY'].find(key=>id==='look-layer-'+key)||null;if(!sizeKey&&!property)return;if(sizeKey)c[sizeKey]=Number(e.target.value);if(property){const selected=lookSelected();if(!selected)return;selected[property]=Number(e.target.value);}const out=document.getElementById(id+'-value');if(out)out.textContent=e.target.value+(property==='angle'?'°':property==='scale'?'%':'');lookRefresh();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-look-action]');if(!b)return;const c=lookCollage(),i=c.materials.findIndex(m=>m.id===c.selected);if(i<0)return;const [layer]=c.materials.splice(i,1);if(b.dataset.lookAction==='front')c.materials.push(layer);else c.selected=c.materials.at(-1)?.id||'photo';lookRefresh();paintScene();});
function lookMovable(key){const c=lookCollage();if(['photo','title','subtitle'].includes(key))return SCENE.look.layout==='free'?c[key]:null;return c.materials.find(m=>m.id===key);}
document.addEventListener('pointerdown',e=>{const node=e.target.closest('#scene-look-preview [data-look-layer]');if(!node||e.button!==0)return;const key=node.dataset.lookLayer,item=lookMovable(key);if(!item)return;e.preventDefault();node.focus({preventScroll:true});const c=lookCollage();if(key!=='title'&&key!=='subtitle'){c.selected=key;const select=document.getElementById('look-layer-select');if(select)select.value=key;const field=document.querySelector('.look-collage-tools fieldset');if(field)field.disabled=false;for(const prop of ['scale','angle']){const input=document.getElementById('look-layer-'+prop),out=document.getElementById('look-layer-'+prop+'-value');if(input)input.value=item[prop];if(out)out.textContent=item[prop]+(prop==='scale'?'%':'°');}const remove=document.querySelector('[data-look-action="remove"]');if(remove)remove.disabled=key==='photo';}const matrix=node.ownerSVGElement.getScreenCTM()?.inverse();if(!matrix)return;const start=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix),initial={x:item.x,y:item.y};node.setPointerCapture(e.pointerId);let moved=false;
 const move=ev=>{if(ev.pointerId!==e.pointerId)return;const point=new DOMPoint(ev.clientX,ev.clientY).matrixTransform(matrix);item.x=Math.max(0,Math.min(600,initial.x+point.x-start.x));item.y=Math.max(0,Math.min(800,initial.y+point.y-start.y));node.setAttribute('transform',`translate(${item.x} ${item.y})${item.scale?` rotate(${item.angle}) scale(${item.scale/100})`:''}`);moved=true;};
 const end=ev=>{if(ev.pointerId!==e.pointerId)return;node.removeEventListener('pointermove',move);node.removeEventListener('pointerup',end);node.removeEventListener('pointercancel',end);if(node.hasPointerCapture(e.pointerId))node.releasePointerCapture(e.pointerId);if(moved){lookRefresh();document.querySelector(`#scene-look-preview [data-look-layer="${key}"]`)?.focus({preventScroll:true});}};node.addEventListener('pointermove',move);node.addEventListener('pointerup',end);node.addEventListener('pointercancel',end);
});
document.addEventListener('keydown',e=>{const n=e.target.closest('#scene-look-preview [data-look-layer]'),delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(!n||!delta)return;const key=n.dataset.lookLayer,item=lookMovable(key);if(!item)return;e.preventDefault();const step=e.shiftKey?10:2;item.x=Math.max(0,Math.min(600,item.x+delta[0]*step));item.y=Math.max(0,Math.min(800,item.y+delta[1]*step));lookRefresh();document.querySelector(`#scene-look-preview [data-look-layer="${key}"]`)?.focus({preventScroll:true});});

function sceneEnterSend(e){if(e.target.id!=='scene-tea-draft'||e.key!=='Enter'||e.shiftKey||e.isComposing||e.keyCode===229||e.defaultPrevented)return;e.preventDefault();if(!SCENE.busy&&sceneTeaState().draft.trim())sceneSendTea();}
document.addEventListener('keydown',sceneEnterSend);
document.addEventListener('submit',e=>{if(e.target.id==='scene-tea-form'){e.preventDefault();sceneSendTea();}});
document.addEventListener('input',e=>{const el=e.target;if(['intent','feeling','details'].includes(e.target.dataset?.guideEdit)){const g=sceneGuide(),key=e.target.dataset.guideEdit;g[key]=e.target.value.slice(0,key==='details'?1000:key==='intent'?600:300);g.confirmed=false;g.referenceRequested=false;g.saved=null;}if(e.target.id==='scene-review-note')SCENE.decision.reviewDraft=e.target.value;if(el.id==='scene-tea-draft'||el.id==='scene-tea-link'){sceneTeaState()[el.id.endsWith('draft')?'draft':'link']=el.value;SCENE.textConsent=false;sceneSync();}if(el.dataset.sceneSummary!==undefined){sceneTeaState().summary.points[Number(el.dataset.sceneSummary)].text=el.value;sceneTeaState().saved=null;const b=$('[data-act="scene-summary-save"]');if(b){b.disabled=false;b.textContent='确认加入灵感池';}}if(el.id==='scene-look-title'||el.id==='scene-look-subtitle'||el.id==='scene-look-goal'){SCENE.look[el.id.replace('scene-look-','')]=el.value;sceneDirty('look');sceneUpdatePreview('look');}if(el.dataset.sceneCrop){const key=el.dataset.sceneCrop;if(!sceneHasLookPhoto()||SCENE.look.loading){el.value=SCENE.look[key];SCENE.error='请先选择一张真实图片，当前预览还是占位图。';sceneSync();return;}SCENE.look[key]=Number(el.value);sceneDirty('look');const out=$('#scene-value-'+key);if(out)out.textContent=el.value+(key==='zoom'?'%':'');sceneUpdatePreview('look',true);}if(el.id==='scene-join-text'){SCENE.join.text=el.value;sceneDirty('join');sceneUpdatePreview('join');}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.scenePhoto)sceneLoadPhoto(el.files?.[0],el.dataset.scenePhoto);if(el.id==='scene-engine'){SCENE.engine=el.value==='local'||(typeof location!=='undefined'&&location.protocol==='file:')?'local':'online';SCENE.textConsent=false;SCENE.imageConsent=false;sceneSync();}if(el.id==='scene-text-consent'){SCENE.textConsent=el.checked;sceneSync();}if(el.id==='scene-image-consent'){SCENE.imageConsent=el.checked;sceneSync();}if(el.id==='scene-existing-photo'){const p=S.pool.find(p=>p.id===el.value&&SceneTools.imageSafe(p.dataUrl));if(p){SCENE.look.photo={url:p.dataUrl,width:p.width||600,height:p.height||800,name:p.name,sourcePoolId:p.id,sourceBy:p.by};sceneDirty('look');paintScene();}}if(el.id==='scene-decision-art'){sceneSelectArt(el.value);sceneUpdateDecision();const review=$('.scene-review-details');if(review)review.outerHTML=sceneReviewHTML();}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el||!el.dataset.act.startsWith('scene-'))return;e.preventDefault();e.stopImmediatePropagation();if(el.disabled)return;const act=el.dataset.act;
 if(act==='scene-go'){sceneGo(el.dataset.page);return;}if(act==='scene-resource'){sceneOpenResource(el.dataset.resource);return;}if(act==='scene-pool'){sceneOpenResource('pool');return;}
 if(act==='scene-game-effects'){sceneGamePlayer();SCENE.game.effects=!SCENE.game.effects;paintScene();return;}
 if(act==='scene-game-egg'){sceneOpenGameEgg();return;}
 if(act==='scene-game-egg-draft'){sceneGameEggDraft();return;}
 if(act==='scene-pool-upload'){openSubmit('upload');S.submit.target='pool';paintSubmit();return;}
 if(act==='scene-pool-collage'){sceneImportPoolImages();return;}
 if(act==='scene-review-aspect'){if(['feeling','palette','layout','type','element'].includes(el.dataset.aspect)){SCENE.decision.reviewAspect=el.dataset.aspect;paintScene();}return;}
 if(act==='scene-review-save'){sceneSaveReview();return;}
 if(act==='scene-channel'){sceneChangeChannel(el.dataset.channel);return;}
 if(act==='scene-audience'){sceneChooseAudience(el.dataset.audience);return;}
 if(act==='scene-guide-edit'){if(!SCENE.busy){const g=sceneGuide();g.stage='confirm';g.confirmed=false;g.saved=null;g.referenceRequested=false;paintScene();}return;}
 if(act==='scene-guide-feeling'){if(!SCENE.busy){sceneGuide().stage='feeling';sceneGuide().confirmed=false;paintScene();}return;}
 if(act==='scene-reference-save'){sceneSaveReference(el.dataset.message,el.dataset.reference);return;}
 if(act==='scene-guide-restart'){if(!SCENE.busy){const g=sceneGuide();g.audience=null;g.confirmed=false;g.referenceRequested=false;paintScene();}return;}
 if(act==='scene-guide-seed'){sceneTeaState().draft=el.dataset.text;const input=$('#scene-tea-draft');if(input){input.value=el.dataset.text;input.focus();}sceneSync();return;}
 if(act==='scene-mood'){if(SCENE.busy)return;const m=SceneTools.moods.find(m=>m.id===el.dataset.mood),g=sceneGuide();if(m&&g.stage==='feeling'){g.mood=m.id;g.feeling=m.label;g.stage='details';g.confirmed=false;paintScene();}return;}
 if(act==='scene-guide-confirm'){const g=sceneGuide();if(SCENE.busy||g.stage!=='confirm')return;if(!g.intent.trim()||!g.details.trim()){SCENE.error='先保留用途和至少一条必留或避开的描述，再确认。';sceneSync();return;}if(g.rights==='pending'){SCENE.error='先说明用图状态，或选择仅探索；不会把未知授权当成已授权。';sceneSync();return;}g.confirmed=true;g.stage='collected';sceneAwardQuest('direction',g.sourceIds?.at(-1));SCENE.notice='方向已记住，接下来由你决定收集什么。';paintScene();return;}
 if(act==='scene-guide-save'){sceneSaveGuidance();return;}
 if(act==='scene-guide-references'){sceneFindGuidanceReferences();return;}
 if(act==='scene-group-spark'){sceneGroupSpark();return;}
 if(act==='scene-proposal-save'){sceneSaveProposal(el.dataset.message);return;}
 if(act==='scene-voice'){sceneStartVoice();return;}
 if(act==='scene-topic'){window.XDPVoice?.cancel();const t=sceneTeaState();if(t.topic===el.dataset.topic)return;t.topics=t.topics||{};t.topics[t.topic]={messages:t.messages,summary:t.summary,saved:t.saved,draft:t.draft,link:t.link,exampleStep:t.exampleStep||0,guides:t.guides};t.topic=el.dataset.topic;Object.assign(t,t.topics[t.topic]||{messages:[TeaScripts.opening(t.topic)],summary:null,saved:null,draft:'',link:'',exampleStep:0,guides:{}});t.revision++;SCENE.textConsent=false;paintScene();}
 if(act==='scene-ai-template'){const template=STUDIO_POSTERS.find(x=>x.posterKey===el.dataset.key);if(template){openSubmit('tpl');S.submit.tpl=template.id;paintSubmit();}}
 if(act==='scene-script-next'){sceneTeaState().exampleStep=Math.min((sceneTeaState().exampleStep||0)+1,TeaScripts.scenario(sceneTeaState().topic).turns.length);paintScene();}
 if(act==='scene-script-reset'){sceneTeaState().exampleStep=0;paintScene();}
 if(act==='scene-script-prompt'){sceneTeaState().draft=TeaScripts.scenario(sceneTeaState().topic).prompts[Number(el.dataset.i)]||'';const input=$('#scene-tea-draft');if(input){input.value=sceneTeaState().draft;input.focus();}sceneSync();}
 if(act==='scene-script-action'){if(el.dataset.page==='templates')sceneOpenResource('templates');else{SCENE.look.layout=el.dataset.layout;sceneDirty('look');sceneGo('look');}}
 if(act==='scene-crop-step'||act==='scene-crop-reset'){if(!sceneHasLookPhoto()||SCENE.look.loading){SCENE.error='请先选择一张真实图片，才能移动和缩放。';sceneSync();return;}const l=SCENE.look;if(act==='scene-crop-reset'){l.x=50;l.y=50;l.zoom=100;}else{const key=el.dataset.key;l[key]=Math.max(key==='zoom'?50:0,Math.min(key==='zoom'?200:100,l[key]+Number(el.dataset.delta)));}sceneDirty('look');for(const key of ['x','y','zoom']){const input=$('#scene-look-'+key),out=$('#scene-value-'+key);if(input)input.value=l[key];if(out)out.textContent=l[key]+(key==='zoom'?'%':'');}sceneUpdatePreview('look',true);}
 if(act==='scene-summary')sceneMakeSummary();if(act==='scene-summary-save')sceneSaveSummary();
 if(act==='scene-tip-use'){SCENE.look.layout=el.dataset.layout;sceneDirty('look');sceneGo('look');}
 if(act==='scene-layout'){SCENE.look.layout=el.dataset.layout;sceneDirty('look');paintScene();}
 if(act==='scene-look-save')sceneSaveLook();if(act==='scene-join-save')sceneSaveJoin();
 if(act==='scene-sticker'){SCENE.join.sticker=el.dataset.sticker;sceneDirty('join');document.querySelectorAll('[data-act="scene-sticker"]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));sceneUpdatePreview('join');}
 if(act==='scene-look-ai'){if(!sceneHasLookContent()){SCENE.error='先选择照片或导入素材，助手才能看图。';sceneSync();return;}if(SCENE.engine!=='online'){SCENE.notice='当前为本地引导：可先比较两种版式，未读取或分析图片。';sceneSync();return;}sceneTask(async()=>{const rev=SCENE.look.revision,goal=SCENE.look.goal;const image=await sceneRaster(sceneLookSVG());if(rev!==SCENE.look.revision)throw Error('预览已改变，本次图片没有发送，请再次点击 @AI。');const result=await sceneRequest('look',goal,image);if(rev===SCENE.look.revision)SCENE.look.reply=[result.highlight,result.reply,result.suggestion].filter(Boolean).join('\n');});}
 if(act==='scene-to-decision'){if(SCENE.look.saved){sceneSelectArt(SCENE.look.saved);sceneGo('decision');}}
 if(act==='scene-variable'){if(SCENE.decision.kind!==el.dataset.kind){sceneSelectArt(SCENE.decision.id);SCENE.decision.kind=el.dataset.kind;sceneUpdateDecision();}}
 if(act==='scene-adjust')sceneAdjust(Number(el.dataset.delta));if(act==='scene-reset'){sceneSelectArt(SCENE.decision.id);sceneUpdateDecision();}
 if(act==='scene-compare'){SCENE.decision.view=el.dataset.view;sceneUpdateDecision();}
 if(act==='scene-direction'){if(SCENE.decision.changed){SCENE.decision.bingo=true;sceneUpdateDecision();}}
 if(act==='scene-decision-save')sceneSaveDecision();if(act==='scene-open-remix')openEdit(SCENE.decision.saved||SCENE.decision.id);
 if(act==='scene-download'){const target=el.dataset.target,svg=target==='look'?sceneLookSVG():target==='join'?sceneJoinSVG():SCENE.decision.view==='before'?SCENE.decision.baseSvg:SCENE.decision.svg;if(!svg)return;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='xingdongpai-'+target+'.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
},true);
// Start with a scene, without an additional overview gate.
if(typeof location!=='undefined'&&location.protocol==='file:')SCENE.engine='local';
sceneTeaState().messages=[TeaScripts.opening('birthday')];WORK.page='tea';paintStudioShell();paintWorkspace();
